questionvariables.text:
f: 3$
lensHeight: 5$
OA: 6$
AB: 1.5$
xF: -f$
xFp: f$
xA: -OA$
xAp: 1/((1/f)+(1/xA))$
gam: xAp/xA$
ABp: gam*AB$

m1e: -AB/xFp$
p1e: AB$
m2: AB/xA$
p2: 0$
m3i: AB/(xA-xF)$
p3i: -m3i*xF$
m3e: 0$
p3e: p3i$

xmin: -8$
xmax: 8$
xtol: 0.5$

found_ray(rayList, mExp, pExp, mtol, ptol) := block([simp, found, r],
  simp: true,
  found: false,
  for r in rayList do (
    if listp(r) and length(r) >= 2 and numberp(r[1]) and numberp(r[2]) then (
      if abs(r[1] - mExp) < mtol and abs(r[2] - pExp) < ptol then found: true
    )
  ),
  found
)$

found_point(ptList, xExp, yExp, tol) := block([simp, found, p],
  simp: true,
  found: false,
  for p in ptList do (
    if listp(p) and length(p) = 3 and numberp(p[2]) and numberp(p[3]) then (
      if abs(p[2] - xExp) < tol and abs(p[3] - yExp) < tol then found: true
    )
  ),
  found
)$

all_pieces_status(pieces, want) := block([simp, ok, pc],
  simp: true,
  ok: true,
  for pc in pieces do (
    if not (listp(pc) and length(pc) >= 3 and is(eff_status(pc[3]) = want)) then ok: false
  ),
  ok
)$

found_ray_status(rayList, mExp, pExp, mtol, ptol, want) := block([simp, found, r],
  simp: true,
  found: false,
  for r in rayList do (
    if listp(r) and length(r) >= 3 and numberp(r[1]) and numberp(r[2]) and listp(r[3]) and length(r[3]) > 0 then (
      if abs(r[1] - mExp) < mtol and abs(r[2] - pExp) < ptol and all_pieces_status(r[3], want) then found: true
    )
  ),
  found
)$

line_pieces(rayList, m, p, mtol, ptol) := block([simp, result, r],
  simp: true,
  result: [],
  for r in rayList do (
    if listp(r) and length(r) >= 3 and numberp(r[1]) and numberp(r[2]) and listp(r[3]) then (
      if abs(r[1] - m) < mtol and abs(r[2] - p) < ptol then result: append(result, r[3])
    )
  ),
  result
)$

/* Cherche d'abord un tronçon qui contient x exactement (sans tolérance) : évite qu'un point situé
   juste à la frontière entre deux tronçons adjacents (ex. avant/après la lentille, tous deux « collés »
   en x=0) ne récupère par erreur le statut du tronçon voisin à cause du padding de tolérance. */
status_covering_x(pieces, x, tol) := block([simp, pc, lo, hi, found],
  simp: true,
  found: -1,
  for pc in pieces do (
    if listp(pc) and length(pc) >= 3 then (
      lo: min(pc[1], pc[2]),
      hi: max(pc[1], pc[2]),
      if x >= lo and x <= hi then found: pc[3]
    )
  ),
  if found = -1 then (
    for pc in pieces do (
      if listp(pc) and length(pc) >= 3 then (
        lo: min(pc[1], pc[2]),
        hi: max(pc[1], pc[2]),
        if x >= lo - tol and x <= hi + tol then found: pc[3]
      )
    )
  ),
  found
)$

/* Un tronçon jamais cliqué (statut par défaut = 0) est considéré réel : seul un clic explicite peut
   le rendre virtuel (2). L'absence (-1) reste distincte (rien n'est tracé à cet endroit). */
eff_status(s) := if s = 0 then 1 else s$

seg_required_status(rayList, m, p, mtol, ptol, xlo, xhi, tol, want) := block([simp, pieces, s1, s2],
  simp: true,
  pieces: line_pieces(rayList, m, p, mtol, ptol),
  s1: status_covering_x(pieces, xlo + tol, tol),
  s2: status_covering_x(pieces, xhi - tol, tol),
  is(eff_status(s1) = want) and is(eff_status(s2) = want)
)$

/* Version "géométrie seule" : le tronçon requis est présent (peu importe son statut réel/virtuel/défaut).
   Sert au crédit partiel (70%) quand le tracé est juste mais le statut est faux. */
seg_required_geom(rayList, m, p, mtol, ptol, xlo, xhi, tol) := block([simp, pieces, s1, s2],
  simp: true,
  pieces: line_pieces(rayList, m, p, mtol, ptol),
  s1: status_covering_x(pieces, xlo + tol, tol),
  s2: status_covering_x(pieces, xhi - tol, tol),
  is(s1 # -1) and is(s2 # -1)
)$

seg_absent(rayList, m, p, mtol, ptol, xlo, xhi, tol) := block([simp, pieces, s1],
  simp: true,
  pieces: line_pieces(rayList, m, p, mtol, ptol),
  s1: status_covering_x(pieces, (xlo + xhi) / 2, tol),
  is(s1 = -1)
)$

seg_optional_status(rayList, m, p, mtol, ptol, xlo, xhi, tol, want) := block([simp],
  simp: true,
  seg_absent(rayList, m, p, mtol, ptol, xlo, xhi, tol) or seg_required_status(rayList, m, p, mtol, ptol, xlo, xhi, tol, want)
)$

found_AB_status(rayList, xExp, y1Exp, y2Exp, xtol, ytol, want) := block([simp, found, r, pc, ylo, yhi, plo, phi],
  simp: true,
  found: false,
  ylo: min(y1Exp, y2Exp),
  yhi: max(y1Exp, y2Exp),
  for r in rayList do (
    if listp(r) and length(r) = 3 and stringp(r[1]) and is(r[1] = "vert") and numberp(r[2])
       and abs(r[2] - xExp) < xtol and listp(r[3]) then (
      for pc in r[3] do (
        if listp(pc) and length(pc) >= 3 then (
          plo: min(pc[1], pc[2]),
          phi: max(pc[1], pc[2]),
          if abs(plo - ylo) < ytol and abs(phi - yhi) < ytol and is(eff_status(pc[3]) = want) then found: true
        )
      )
    )
  ),
  found
)$

require_mc(mc) := block(
  if not is(safe_op(mc) = "lentille_construction") or not is(length(mc) = 2) then
    "La réponse doit être générée par la construction graphique ci-dessus (fonction lentille_construction(rayons, points))."
  else
    true
)$

ans1_validator(ex) := stack_seq_validator(ex, [require_mc])$
